<script lang="ts">
 import {onMount,tick} from 'svelte'
 import {collectionRecords,appendUnique} from '../../studies/expansion.mjs'
 const uid=$props.id()
 let mounted=$state(false),records=$state(collectionRecords()),mode=$state('page'),page=$state(1),loaded=$state(6),fail=$state(false),regional=$state(false),message=$state(''),selected=$state<number[]>([]),detail=$state(0)
 const visible=$derived(mode==='page'?records.slice((page-1)*6,page*6):records.slice(0,loaded))
 const totalPages=$derived(Math.max(1,Math.ceil(records.length/6)))
 function url(next=page,note=detail){const u=new URL(location.href);u.searchParams.set('collection-page',String(next));u.searchParams.set('collection-mode',mode);u.searchParams.set('collection-loaded',String(loaded));if(note)u.searchParams.set('collection-note',String(note));else u.searchParams.delete('collection-note');return u.pathname+u.search+u.hash}
 function sync(replace=false){history[replace?'replaceState':'pushState']({},'',url())}
 async function restore(){const u=new URL(location.href);page=Math.min(totalPages,Math.max(1,Number(u.searchParams.get('collection-page'))||1));mode=u.searchParams.get('collection-mode')==='append'?'append':'page';loaded=Math.min(records.length,Math.max(6,Number(u.searchParams.get('collection-loaded'))||6));const previous=detail;detail=Number(u.searchParams.get('collection-note'))||0;await tick();if(previous&&!detail)document.getElementById(`${uid}-record-${previous}`)?.focus()}
 onMount(()=>{mounted=true;restore();window.addEventListener('popstate',restore);return()=>window.removeEventListener('popstate',restore)})
 async function next(){if(fail){fail=false;message='Next chunk failed. Existing records and selection retained; retry when ready.';return}if(mode==='page')page=Math.min(totalPages,page+1);else{const combined=appendUnique(records.slice(0,loaded),records.slice(loaded,loaded+6));loaded=combined.length}message=`Showing ${mode==='page'?visible.length:loaded} records; ${selected.length} selected.`;sync()}
 async function open(id:number){detail=id;sync();await tick();document.getElementById(`${uid}-detail`)?.focus()}
 async function remove(id:number){const index=visible.findIndex(r=>r.id===id);records=records.filter(r=>r.id!==id);selected=selected.filter(value=>value!==id);page=Math.min(page,totalPages);loaded=Math.min(loaded,records.length);sync(true);message=`Removed record ${id}. ${records.length} remain.`;await tick();const next=visible[Math.min(index,visible.length-1)];document.getElementById(next?`${uid}-record-${next.id}`:`${uid}-heading`)?.focus()}
</script>
<section class="task-study" data-study="large-collection" aria-label="Twenty-four local records"><h4 id={`${uid}-heading`} tabindex="-1">Research collection</h4><p>24 initial local records. Page or append without changing their identity. The original four-record studies remain separate.</p><fieldset disabled={!mounted}><legend class="study-sr">Collection controls</legend>
{#if detail}<article><h4 id={`${uid}-detail`} tabindex="-1">Research note {detail}</h4><p>Local detail. Return to the same collection context.</p><button class="btn" onclick={async()=>{const id=detail;detail=0;sync();await tick();document.getElementById(`${uid}-record-${id}`)?.focus()}}>Return to records</button></article>
{:else}<div class="study-controls"><label>Retrieval<select class="select" bind:value={mode} onchange={()=>{page=1;loaded=6;message='Retrieval changed; selected identities retained.';sync()}}><option value="page">Pagination</option><option value="append">Load more</option></select></label><label class="check"><input class="checkbox" type="checkbox" bind:checked={fail}/> Fail next chunk</label><label class="check"><input class="checkbox" type="checkbox" bind:checked={regional}/> Fail optional summary</label></div>
<p>{regional?'Summary unavailable. Records remain usable.':`Summary: ${records.length} local records.`}</p>{#if regional}<button class="btn" onclick={()=>regional=false}>Retry optional summary</button>{/if}
<p>{selected.length} selected across the local collection; selection survives paging.</p><ul class="study-results">{#each visible as record (record.id)}<li><label class="check"><input class="checkbox" type="checkbox" value={record.id} bind:group={selected}/> Select {record.name}</label><a id={`${uid}-record-${record.id}`} href={`?collection-page=${page}&collection-note=${record.id}`} onclick={e=>{e.preventDefault();open(record.id)}}>{record.name}</a><button class="btn" onclick={()=>remove(record.id)}>Remove {record.name}</button></li>{/each}</ul>
<div class="study-actions">{#if mode==='page'}<button class="btn" disabled={page<=1} onclick={()=>{page--;sync();message=`Page ${page}.`}}>Previous page</button><span>Page {page} of {totalPages}</span>{/if}<button class="btn" disabled={mode==='page'?page>=totalPages:loaded>=records.length} onclick={next}>{mode==='page'?'Next page':'Load more records'}</button></div>{/if}
<p role="status">{message}</p><button class="btn" onclick={()=>{records=collectionRecords();mode='page';page=1;loaded=6;selected=[];detail=0;regional=fail=false;message='Collection reset.';sync(true)}}>Reset collection</button></fieldset><p>Find and print see currently rendered records. This example does not virtualize a hidden full collection.</p><noscript>Initial records are readable. Enhanced paging requires JavaScript.</noscript></section>
<style>.study-results li{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.study-results a{flex:1 1 10rem}</style>
